import{C as e,H as t,R as n,S as r,Z as i,v as a,w as o,x as s}from"./vue-BDYVXuuN.js";import{c}from"./app-m3La2wLh.js";var l=JSON.parse(`{"path":"/courses/zsb-english/l/13/","title":"第 13 课 · 名词性从句 Noun Clauses | 备考·英语","lang":"zh-CN","frontmatter":{"title":"第 13 课 · 名词性从句 Noun Clauses","createTime":"2026-09-09T22:39:43.000Z","permalink":"/courses/zsb-english/l/13/","banner":"/images/covers/zsb-english.png","description":"这是本课阅读版。即可在同一页阅读、作答与复习，学习记录保存在此设备。 / 01 · 语法专题 / 第十三课 语法专题 · 第十三课 对应教材上册 P83、P115–P123 · 考引导词选择（缺不缺成分 + 含义）、陈述语序、it 作形式主/宾语、whether 与 if 七区别、四种从句辨析。 考点地图 · 点击跳转 什么是名词性从句：主语从句、宾语...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"第 13 课 · 名词性从句 Noun Clauses\\",\\"image\\":[\\"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png\\"],\\"dateModified\\":\\"2026-10-07T13:23:39.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://liuj66794-sys.github.io/blog/courses/zsb-english/l/13/"}],["meta",{"property":"og:site_name","content":"知序"}],["meta",{"property":"og:title","content":"第 13 课 · 名词性从句 Noun Clauses"}],["meta",{"property":"og:description","content":"这是本课阅读版。即可在同一页阅读、作答与复习，学习记录保存在此设备。 / 01 · 语法专题 / 第十三课 语法专题 · 第十三课 对应教材上册 P83、P115–P123 · 考引导词选择（缺不缺成分 + 含义）、陈述语序、it 作形式主/宾语、whether 与 if 七区别、四种从句辨析。 考点地图 · 点击跳转 什么是名词性从句：主语从句、宾语..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-07T13:23:39.000Z"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:image:src","content":"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png"}],["meta",{"name":"twitter:image:alt","content":"第 13 课 · 名词性从句 Noun Clauses"}],["meta",{"property":"article:modified_time","content":"2026-10-07T13:23:39.000Z"}],["link",{"rel":"canonical","href":"https://liuj66794-sys.github.io/blog/courses/zsb-english/l/13/"}]]},"readingTime":{"minutes":73.24,"words":21973},"git":{"createdTime":1791379419000,"updatedTime":1791379419000,"contributors":[{"name":"38623","username":"","email":"386239680@qq.com","commits":1,"avatar":"https://gravatar.com/avatar/6a2940d3ff3182b82cb8a2c8dfebb295d647509713aef8bc86fb9e95a6767f99?d=retro"}]},"autoDesc":true,"filePathRelative":"courses/zsb-english/l/13.md","headers":[]}`),u={name:`13.md`};function d(c,l,u,d,f,p){let m=t(`VPLink`);return n(),s(`div`,null,[a(`blockquote`,null,[a(`p`,null,[l[1]||=e(`这是本课阅读版。`,-1),o(m,{href:`/blog/lessons/zsb-english/lessons/0013-noun-clauses.html`},{default:i(()=>[...l[0]||=[a(`strong`,null,`打开互动课程`,-1)]]),_:1}),l[2]||=e(`即可在同一页阅读、作答与复习，学习记录保存在此设备。`,-1)])]),a(`p`,null,[o(m,{href:`/blog/lessons/zsb-english/lessons/course.html`},{default:i(()=>[...l[3]||=[e(`课程总览`,-1)]]),_:1}),l[4]||=e(` / 01 · 语法专题 / 第十三课`,-1)]),l[10]||=r(`<p>语法专题 · 第十三课</p><p>对应教材上册 P83、P115–P123 · 考引导词选择（缺不缺成分 + 含义）、陈述语序、it 作形式主/宾语、whether 与 if 七区别、四种从句辨析。</p><div class="hint-container info"><p class="hint-container-title">考点地图 · 点击跳转</p><ol><li><a href="#pt-1"><strong>什么是名词性从句</strong>：主语从句、宾语从句、表语从句、同位语从句</a></li><li><a href="#pt-2"><strong>引导词</strong>：不作成分三类（that / whether / 四条大何）vs 作成分的 5W + 四步解题法</a></li><li><a href="#pt-3"><strong>名词性从句的语序</strong>：一律陈述语序</a></li><li><a href="#pt-4"><strong>it 在名词性从句中的使用</strong>：形式主语 4 句型、形式宾语</a></li><li><a href="#pt-5"><strong>whether 与 if 七区别</strong> + <strong>宾语从句中的否定转移</strong></a></li></ol></div><h2 id="第一部分-·-什么是名词性从句-教材-p83-p115" tabindex="-1"><a class="header-anchor" href="#第一部分-·-什么是名词性从句-教材-p83-p115"><span>第一部分 · 什么是名词性从句（教材 P83/P115）</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第一部分 · 什么是名词性从句（教材 P83/P115）</p><ul><li><strong>目标</strong>：解决“这句话算什么从句”：先看从句站在什么位置（谓语前、动词/介词后、系动词后、抽象名词后），再按位置定类型。</li><li><strong>建议用时</strong>：12 分钟</li><li><strong>知识点</strong>：<code>名词性从句的四种类型与位置判定</code></li></ul></div><h3 id="第一部分-·-什么是名词性从句-教材-p83-p115-·-小步学" tabindex="-1"><a class="header-anchor" href="#第一部分-·-什么是名词性从句-教材-p83-p115-·-小步学"><span>第一部分 · 什么是名词性从句（教材 P83/P115） · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>名词性从句：把一件事放进句子</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>名词性从句是怎么来的：同一句话放进不同位置</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>主语从句缺主语：What makes me feel surprised is that…</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：用一句话说明名词性从句的四种类别是靠什么判断的，并各举一个例子。</p><div class="hint-container tip"><p class="hint-container-title">名词性从句是怎么来的：同一句话放进不同位置</p><p><strong>句意</strong>：That he won this game was surprising. 意思是“他赢得了这场比赛，这很令人惊讶”。</p><p><strong>拆解</strong></p><ul><li>That he won this game 是主语从句：它站在主句谓语 was 之前，占了原本名词的位置（原本可说 The news was surprising.）</li><li>that 只起连接作用，不作从句成分、也没有含义</li><li>he won this game 是完整的“主语 + 谓语 + 宾语”，所以不需要别的引导词来补成分</li><li>was surprising 是主句的谓语和表语，说明这件事的性质</li></ul><p><strong>语法</strong>：名词表示人或事物的名称，在句中作主语、宾语、表语、同位语。本该由名词充当的位置改由一个句子来充当，这个句子就是名词性从句：在谓语之前是主语从句，在动词、介词或形容词之后是宾语从句，在系动词之后是表语从句，在 fact、news、idea 等抽象名词之后是同位语从句。</p><p>正例：That he won this game was surprising.（主语从句）；I know that Ma Yun is rich.（宾语从句）；The fact is that Ma Yun is rich.（表语从句）；The fact that Ma is rich is true.（同位语从句，说明 the fact 的内容） 反例：把 That he won this game 当成定语从句 ×（它在谓语前作主语，没有修饰任何名词）；在句首用 If 引导主语从句 ×（if 不能引导主语从句，要用 whether）；把 The fact is that Ma Yun is rich. 里的 that 从句当成定语从句 ×（它在系动词后作表语） 适用边界：位置决定类型：同一句话放进不同位置就变成不同的从句。从句作主语时主句谓语用单数（That he won this game was surprising.）；if 不能引导主语从句，表“是否”一律用 whether。</p><p><strong>口诀</strong>：名词的位置由句子来占，就是名词性从句 —— 先看从句站在哪儿：谓语前是主语从句、动词/介词/形容词后是宾语从句、系动词后是表语从句、抽象名词后是同位语从句。</p></div><div class="hint-container tip"><p class="hint-container-title">主语从句缺主语：What makes me feel surprised is that…</p><p><strong>句意</strong>：What makes me feel surprised is that he made such a success. 意思是“让我感到吃惊的是他竟然取得了这样的成功”。</p><p><strong>拆解</strong></p><ul><li>What makes me feel surprised 是主语从句，位于主句谓语 is 之前</li><li>what 在从句里作主语（makes 前是空的）——它既连接从句，又在从句中充当成分</li><li>is 是主句的系动词，that he made such a success 是表语从句，说明“吃惊的内容”</li><li>全句结构是“主语从句 + is + 表语从句”，两空要分别判断</li></ul><p><strong>语法</strong>：主语从句缺主语、宾语或定语时用连接代词 what/who/whom/which/whose：what 本身要作成分，不能换成 that（that 不作成分，要求从句完整）。从句完整、无含义用 that；表“是否”用 whether（不用 if）；有“如何/何时/何地/为什么”的含义用 how/when/where/why。</p><p>正例：What makes me feel surprised is that he made such a success.；What surprised us most was his sudden decision to quit the job.；That he often forgot their wedding anniversary greatly annoyed his wife.（从句完整 → that） 反例：That makes me feel surprised is… ×（makes 前缺主语，从句不完整，that 不作成分）；It makes me feel surprised is… ×（It 不能连接两个句子）；Which makes me feel surprised is… ×（which 需要选择范围） 适用边界：两空题要分别判断：前半缺成分用连接代词（What 等），后半完整无含义才用 that；主语从句作主语时，主句谓语仍用单数（is/was）。</p><p><strong>口诀</strong>：缺成分用 What，不缺成分用 That —— what 一定在从句里当主语或宾语；that 只连接、不占位置，用 that 的前提是从句本身完整。</p></div><p>名词表示人或事物的名称，在句中作<strong>主语、宾语、表语、同位语</strong>等。本该由<strong>名词</strong>充当这些位置、现在由<strong>一个句子</strong>来充当——这个句子就是<strong>名词性从句</strong>。</p><p>四种从句的由来（同一句话放进不同位置）：</p><table><thead><tr><th>例句</th><th>从句类型</th></tr></thead><tbody><tr><td><strong>Ma Yun is rich</strong> is true.（原本：The fact is true.）</td><td><strong>主语从句</strong></td></tr><tr><td>I know <strong>that Ma Yun is rich</strong>.（原本：I know the fact.）</td><td><strong>宾语从句</strong></td></tr><tr><td>The fact is <strong>that Ma Yun is rich</strong>.（原本：The fact is that Ma is rich.）</td><td><strong>表语从句</strong></td></tr><tr><td>The fact <strong>that Ma is rich</strong> is true.（说明 the fact 的内容）</td><td><strong>同位语从句</strong></td></tr></tbody></table><h2 id="第二部分-·-名词性从句的引导词-教材-p116" tabindex="-1"><a class="header-anchor" href="#第二部分-·-名词性从句的引导词-教材-p116"><span>第二部分 · 名词性从句的引导词（教材 P116）</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第二部分 · 名词性从句的引导词（教材 P116）</p><ul><li><strong>目标</strong>：解决“这个空该填哪一类引导词”：用四步法（划从句 → 看类型 → 看成分 → 看含义）把选项分成“作成分的 5W”和“不作成分的三类”，再收紧到唯一答案。</li><li><strong>建议用时</strong>：15 分钟</li><li><strong>知识点</strong>：<code>名词性从句的引导词两类与四步解题法</code> <code>名词性从句一律用陈述语序</code> <code>同位语从句与抽象名词</code></li></ul></div><h3 id="第二部分-·-名词性从句的引导词-教材-p116-·-小步学" tabindex="-1"><a class="header-anchor" href="#第二部分-·-名词性从句的引导词-教材-p116-·-小步学"><span>第二部分 · 名词性从句的引导词（教材 P116） · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>名词性从句：把一件事放进句子</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>引导词分两班：不作成分的三类与作成分的五个 W</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>同位语从句：抽象名词后面的 that 不能说省就省</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>一律陈述语序：宾语从句与表语从句里的“不倒装”</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：背出四步法，并说明“不缺成分”时能用哪几类引导词、“缺成分”时能用哪几类。</p><div class="hint-container tip"><p class="hint-container-title">引导词分两班：不作成分的三类与作成分的五个 W</p><p><strong>句意</strong>：I wonder whether I should tell her the truth. 意思是“我不知道是否应该告诉她真相”；What she said left a deep impression on me. 意思是“她说的话给我留下了很深的印象”。</p><p><strong>拆解</strong></p><ul><li>第一句：whether I should tell her the truth 的主语、谓语、宾语齐全，whether 不作成分，只表示“是否”</li><li>第二句：What she said 里 said 缺宾语，what 既连接从句、又作 said 的宾语</li><li>小结：从句不缺成分 → that（无含义）/ whether（是否）/ when、where、why、how（有含义）；从句缺主语、宾语、定语 → who、whom、what、which、whose</li><li>四步解题法：①划从句（从引导词划到空后的第二个谓语之前）②看类型 ③看成分 ④看含义</li></ul><p><strong>语法</strong>：引导词分两类：不作从句成分的有 that、whether、连接副词 when/where/why/how；作从句成分的连接代词有 who（主语）、whom（宾语）、what（主宾）、which（定语）、whose（定语）。解题按“划从句 → 看类型 → 看成分 → 看含义”四步推进。</p><p>正例：I wonder whether I should tell her the truth.（不缺成分，whether 表“是否”）；That he misspelled the word made everyone happy.（不缺成分、无含义 → that）；What she said left a deep impression on me.（缺宾语 → what）；Do you know who won the game?（缺主语 → who） 反例：I wonder that I should tell her the truth. ×（“是否”要用 whether，that 无含义）；That she said left a deep impression on me. ×（said 缺宾语，that 不作成分）；Do you know whom won the game? ×（从句缺主语，whom 只作宾语） 适用边界：“删掉引导词从句含义是否完整”是判断含义的最后一步：完整说明引导词无义（that），不完整说明引导词有义（whether/how/when…）。连接代词一定在从句里作主语、宾语或定语，不能与 that 混用。</p><p><strong>口诀</strong>：划从句 → 看类型 → 看成分 → 看含义 —— 四步顺序固定：先划出从句范围，再看它在句中作什么成分，再看从句内部缺什么，最后看含义是否完整（完整说明引导词无义）。</p></div><div class="hint-container tip"><p class="hint-container-title">同位语从句：抽象名词后面的 that 不能说省就省</p><p><strong>句意</strong>：We heard the news that our team had won the game. 意思是“我们听说了我们队赢得比赛的消息”。</p><p><strong>拆解</strong></p><ul><li>the news 是抽象名词，that our team had won the game 说明这条“消息”的具体内容</li><li>从句 our team had won the game 主语、谓语、宾语齐全，that 不作任何成分，只起连接作用</li><li>that 不能省略，也不能换成 which</li><li>对比：The suggestion that he raised at the meeting is very good. 里 raised 缺宾语，that 是作宾语的关系代词 → 那是定语从句</li></ul><p><strong>语法</strong>：同位语从句跟在 idea、fact、news、hope、belief、thought、doubt、promise、suggestion、order、possibility 等抽象名词后面，解释该名词的具体内容；引导词用 that（不作成分、不可省略），也可用 when、where、why、how、whether。与定语从句的分水岭是：从句里的 that 是否充当成分。</p><p>正例：We heard the news that our team had won the game.；The fact that Helen was late for the weekly meeting again made the manager very angry.；There is an idea that too much stress can partly cause the disease. 反例：We heard the news which our team had won the game. ×（从句完整，which 没有位置）；把 The suggestion that he raised at the meeting is very good. 说成同位语从句 ×（raised 缺宾语，that 作宾语 → 定语从句） 适用边界：只有“说明内容”的抽象名词后才是同位语从句；一旦从句里缺主语或宾语（that 充当了成分），那就是定语从句。whether 也能引导同位语从句（the question whether…），if 不能。</p><p><strong>口诀</strong>：that 不占位置就是在说内容（同位语），that 占位置就是在修饰名词（定语从句） —— 判断方法：把 that 拿掉，从句是否完整——完整就是同位语从句。</p></div><div class="hint-container tip"><p class="hint-container-title">一律陈述语序：宾语从句与表语从句里的“不倒装”</p><p><strong>句意</strong>：Could you please tell me how you improve your writing? 意思是“你能告诉我你是怎样提高写作的吗”；The reason for his absence is that he missed the early bus. 意思是“他缺席的原因是他错过了早班公交车”。</p><p><strong>拆解</strong></p><ul><li>第一句：宾语从句 how you improve your writing 用陈述语序（主语 you + 谓语 improve），不能写成 how do you improve</li><li>第二句：表语从句放在系动词 is 之后；主语是 reason 时连接词用 that，不用 because</li><li>对比方向：That is why he was late.（那是他迟到的原因——why 后接结果）／That was because he was caught in a traffic jam.（那是因为他遇上了堵车——because 后接原因）</li><li>宾语从句还能跟在介词后（They are talking about whether…）和形容词后（I am happy that you can join us.）</li></ul><p><strong>语法</strong>：名词性从句一律用陈述语序（主语 + 谓语），不用疑问语序。宾语从句跟在动词、介词、形容词之后；表语从句放在系动词之后，主语为 reason 时连接词用 that。</p><p>正例：Could you please tell me how you improve your writing?；They are talking about whether they should accept the offer.（介词后的宾语从句）；The reason for his absence is that he missed the early bus.（reason 作主语 → that） 反例：Could you please tell me how do you improve your writing? ×（从句里不用疑问语序）；The reason for his absence is because he missed the early bus. ×（reason 作主语时表语从句用 that）；That was why he was caught in a traffic jam. ×（表意颠倒：先说结果才用 why，先给结果再解释原因用 because） 适用边界：陈述语序说的是从句内部的语序，主句仍可用 Could you… 的委婉疑问。表语从句里 because 与 why 方向相反，主语是 reason 时必须用 that。</p><p><strong>口诀</strong>：主句怎么问都行，从句一律陈述语序 —— 选项里出现 do you/is he 这种倒装写在从句内部的，基本可以直接排除。</p></div><h3 id="_1-不作从句成分的三类引导词-从句不缺成分时用" tabindex="-1"><a class="header-anchor" href="#_1-不作从句成分的三类引导词-从句不缺成分时用"><span>1. 不作从句成分的三类引导词（从句不缺成分时用）</span></a></h3><ul><li><strong>① that</strong>：不作成分；无含义：<strong>That</strong> he misspelled the word made everyone happy. 他拼错了这个单词，这让大家都笑了。</li><li><strong>② whether</strong>：不作成分；含义&quot;是否&quot;：I wonder <strong>whether</strong> I should tell her the truth. 我不知道是否应该告诉她真相。They also surveyed <strong>whether</strong> they had a family dog or not.<strong>Whether</strong> I should tell her the truth is unknown.</li><li><strong>③ 连接副词&quot;四条大何&quot; when / where / why / how</strong>：不作主要成分，<strong>有含义</strong>：He doesn&#39;t know <strong>why</strong> he can find a girlfriend.</li></ul><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>小结当名词性从句中<strong>不缺成分</strong>时，可以用 <strong>that / whether / 四条大何（when/where/why/how）</strong>来引导。</p></div><h3 id="_2-作从句成分的连接代词-5-个-w-从句缺成分时用" tabindex="-1"><a class="header-anchor" href="#_2-作从句成分的连接代词-5-个-w-从句缺成分时用"><span>2. 作从句成分的连接代词&quot;5 个 W&quot;（从句缺成分时用）</span></a></h3><table><thead><tr><th>引导词</th><th>所作成分</th><th>含义</th></tr></thead><tbody><tr><td>who</td><td>主语</td><td>谁</td></tr><tr><td>whom</td><td>宾语</td><td>谁</td></tr><tr><td>what</td><td>主、宾</td><td>什么（物）</td></tr><tr><td>which</td><td>定语</td><td>哪一个</td></tr><tr><td>whose</td><td>定语</td><td>谁的</td></tr></tbody></table><p><strong>What</strong> she said left a deep impression on me.（what 作 said 的宾语） Do you know <strong>who</strong> won the game?（who 作从句主语） I know the girl <strong>whose</strong> hair is long and straight.（whose 作定语）</p><h3 id="_3-四步解题法" tabindex="-1"><a class="header-anchor" href="#_3-四步解题法"><span>3. 四步解题法</span></a></h3><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>口诀<strong>划从句 → 看类型 → 看成分 → 看含义</strong></p><p>① <strong>划从句</strong>：从引导词（或设空处）开始划，划到引导词后（空后）的第二个谓语动词之前（若引导词后只有一个谓语动词，则划到句子最后）</p><p>② <strong>看类型</strong>：根据从句的位置判断从句类型</p><p>③ <strong>看成分</strong>：从句缺主语/宾语/定语 → 从&quot;作成分&quot;的 5W 中选；不缺成分 → 从&quot;不作成分&quot;三类中选</p><p>④ <strong>看含义</strong>：删掉引导词后从句含义完整 → 引导词无含义（that）</p></div><h3 id="_4-名词性从句的语序-教材-p116-补充" tabindex="-1"><a class="header-anchor" href="#_4-名词性从句的语序-教材-p116-补充"><span>4. 名词性从句的语序（教材 P116 补充）</span></a></h3><div class="hint-container info"><p class="hint-container-title">本节指引 · 第三部分 · 主语从句（教材 P117）</p><ul><li><strong>目标</strong>：解决“主语从句该用哪个引导词、什么时候用 it 顶位”：按 What / That / How / Whether 四条线选词，并会用 it 作形式主语与 What…is that… 套娃结构。</li><li><strong>建议用时</strong>：12 分钟</li><li><strong>知识点</strong>：<code>主语从句的引导词选择</code> <code>it 作形式主语与形式宾语</code></li></ul></div><h3 id="第三部分-·-主语从句-教材-p117-·-小步学" tabindex="-1"><a class="header-anchor" href="#第三部分-·-主语从句-教材-p117-·-小步学"><span>第三部分 · 主语从句（教材 P117） · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>名词性从句：把一件事放进句子</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>主语从句的四种引导方式：What / That / How / Whether</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>it 作形式主语：It is important that…</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>两个从句套在一起：What…is that… 的两空判断</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：说出主语从句的四种引导方式各用在哪一步；再用一个例子说明 it 作形式主语时哪部分才是真正的主语。</p><div class="hint-container tip"><p class="hint-container-title">主语从句的四种引导方式：What / That / How / Whether</p><p><strong>句意</strong>：How we can solve the problem efficiently requires careful discussion. 意思是“我们如何高效地解决这个问题需要认真讨论”。</p><p><strong>拆解</strong></p><ul><li>How we can solve the problem efficiently 是主语从句，位于主句谓语 requires 之前</li><li>从句 we can solve the problem efficiently 主语、谓语、宾语齐全，缺的是“如何”这层方式含义</li><li>有含义 → 用 how（四条大何之一）；如果从句完整又没有含义，就换成 that</li><li>表“是否”时用 whether，不用 if</li></ul><p><strong>语法</strong>：主语从句缺主语时用 what，缺宾语时用 what/whom，缺定语时用 which/whose；从句完整时按含义选：无含义用 that，表“是否”用 whether，有“如何/何时/何地/为什么”的含义用 how/when/where/why。主语从句作主语时，主句谓语用单数。</p><p>正例：How we can solve the problem efficiently requires careful discussion.；What surprised all of us was that he canceled the meeting.；Whether the team will win the championship depends on their performance.；That he often forgot their wedding anniversary greatly annoyed his wife. 反例：If the team will win the championship depends on… ×（if 不能引导主语从句）；That surprised all of us was that he canceled the meeting. ×（surprised 缺主语，要用 What）；What we can solve the problem efficiently requires… ×（从句完整，what 没有位置） 适用边界：主语从句作主语时主句谓语用单数；if 不能引导主语从句，表“是否”一律用 whether。两个从句套用时，两空要分别判断。</p><p><strong>口诀</strong>：缺成分找 What，不缺成分看含义：无义 that、是否 whether、其余四条大何 —— 按顺序问自己：缺成分吗（缺就用 What 等连接代词）→ 不缺：有没有含义（没有用 that，是“是否”用 whether，其余用 how/when/where/why）。</p></div><div class="hint-container tip"><p class="hint-container-title">it 作形式主语：It is important that…</p><p><strong>句意</strong>：It is important that we should protect the environment. 意思是“我们应当保护环境，这一点很重要”。</p><p><strong>拆解</strong></p><ul><li>真正的主语是 that we should protect the environment，它太长，于是放到后面</li><li>it 是形式主语，先占住主语的位置，让主句先说完“很重要”</li><li>主句结构是 It is + 形容词 + that 从句；换成名词、分词、不及物动词同样成立：It is a fact that…／It is reported that…／It happened that…</li><li>It is known to us all that… 译“我们都知道……”；不能说 As is known to us all that…</li></ul><p><strong>语法</strong>：常用 it 作形式主语的四种句型：It is + 名词 + 从句；It is + 形容词 + that；It is + 分词 + that；It + 不及物动词（happen、doesn&#39;t matter 等）+ that。It is/was said/reported/believed/estimated that… = sb./sth. be said/reported/… to do。</p><p>正例：It is important that we should protect the environment.；It is a fact that the earth goes round the sun.；It is reported that she will go abroad soon. = She is reported to go abroad soon.；It happened that I saw her three days ago. 反例：What is important that we should protect the environment. ×（这是 It 作形式主语的固定句型，不用 what）；As is known to us all that the 2022 Winter Olympics will be held in Beijing. ×（as 引导非限制性定语从句要加逗号，也不能这样接 that 从句） 适用边界：形式主语只解决“头重脚轻”，从句本身仍是主语从句，还原到句首（That we should protect the environment is important.）意思不变。as 引导非限制性定语从句要加逗号（As is known to all, …），不能直接接 that 从句。</p><p><strong>口诀</strong>：头重脚轻用 It 顶，真主语放后面 —— 看到“It is + 形容词/名词/分词 + that 从句”，立刻想到形式主语：it 只占位置，that 从句才是真正的主语。</p></div><div class="hint-container tip"><p class="hint-container-title">两个从句套在一起：What…is that… 的两空判断</p><p><strong>句意</strong>：What I can&#39;t understand is that he wants to change his mind. 意思是“我不能理解的是他竟然想改变主意”。</p><p><strong>拆解</strong></p><ul><li>What I can&#39;t understand 是主语从句，what 作 understand 的宾语</li><li>is 是主句的系动词</li><li>that he wants to change his mind 是表语从句：从句完整、无含义 → that</li><li>两空各管一段：前半缺成分用 what，后半完整用 that</li></ul><p><strong>语法</strong>：“主语从句 + is + 表语从句”是本课的高频套娃结构，两个空要分别判断：主语从句里缺主语或宾语用连接代词（What 等），表语从句里从句完整就用 that。</p><p>正例：What I can&#39;t understand is that he wants to change his mind.；What surprised us most was that he quit his job.；It is known to us all that the 2022 Winter Olympics will be held in Beijing. 反例：That I can&#39;t understand is that he wants to change his mind. ×（understand 缺宾语，要用 What）；What I can&#39;t understand is what he wants to change his mind. ×（第二空从句完整，用 that 即可） 适用边界：前空缺成分用 What，后空完整用 That；第二空若从句完整却填了 what/why，就会与句意冲突。</p><p><strong>口诀</strong>：前空缺成分用 What，后空完整用 That —— 遇到两个空的题不要用同一个引导词应付：分别把两个从句单独读一遍，缺成分的用 what，完整的用 that。</p></div><div class="hint-container caution"><p class="hint-container-title">易错</p><p>一律陈述语序名词性从句常用<strong>陈述语序（主语 + 谓语）</strong>，不用疑问语序：</p><p><strong>That he won this game was</strong> surprising. 他赢得了这场比赛，这很令人惊讶。 <strong>When we can begin the project is</strong> still under discussion. 我们何时才能开始这项工程仍在讨论中。</p></div><h2 id="第三部分-·-主语从句-教材-p117" tabindex="-1"><a class="header-anchor" href="#第三部分-·-主语从句-教材-p117"><span>第三部分 · 主语从句（教材 P117）</span></a></h2><p>在复合句中充当<strong>主语</strong>成分的句子叫主语从句。</p><h3 id="拓展-·-常用-it-作形式主语-4-种句型" tabindex="-1"><a class="header-anchor" href="#拓展-·-常用-it-作形式主语-4-种句型"><span>拓展 · 常用 it 作形式主语（4 种句型）</span></a></h3><div class="hint-container info"><p class="hint-container-title">本节指引 · 第四部分 · 宾语从句（教材 P119–120）</p><ul><li><strong>目标</strong>：解决“宾语从句的引导词、语序、时态、it 形式宾语与否定转移”：会分辨动词/介词/形容词后的从句，会用 it + 形容词 + that 的固定语序，并分清 whether 与 if。</li><li><strong>建议用时</strong>：15 分钟</li><li><strong>知识点</strong>：<code>宾语从句的位置、that 省略与主句时态呼应</code> <code>it 作形式主语与形式宾语</code> <code>whether 与 if 的七种区别</code> <code>whoever/whatever 等 -ever 引导词</code> <code>宾语从句中的否定转移</code></li></ul></div><h3 id="第四部分-·-宾语从句-教材-p119–120-·-小步学" tabindex="-1"><a class="header-anchor" href="#第四部分-·-宾语从句-教材-p119–120-·-小步学"><span>第四部分 · 宾语从句（教材 P119–120） · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>名词性从句：把一件事放进句子</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>宾语从句的三种位置与 that 不能省的 5 种情况</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>whether 与 if 的七种区别</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>否定转移与 -ever 类引导词：whoever = anyone who</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：说出 whether 必用的七种情况中的任意五种，并说明 it + 形容词 + that 的语序为什么不能改。</p><div class="hint-container tip"><p class="hint-container-title">宾语从句的三种位置与 that 不能省的 5 种情况</p><p><strong>句意</strong>：I think it necessary that we take plenty of hot water every day. 意思是“我认为我们每天带足热水是必要的”。</p><p><strong>拆解</strong></p><ul><li>it 是形式宾语，真正的宾语是 that we take plenty of hot water every day</li><li>语序固定为“动词 + it + 形容词 + that 从句”：think/find/consider/believe + it + adj. + that</li><li>这一句型里的 that 不能省略，it 也不能换成 this/that</li><li>宾语从句还能跟在介词后（It depends on what it is.）和形容词后（I am happy that you can join us.）</li></ul><p><strong>语法</strong>：宾语从句跟在动词、介词、形容词之后。that 不作成分、无实义，口语中可省略；但在 5 种情况下不省略：①find/believe/think/consider/make + it + adj. + that 句型；②作双宾语中的直接宾语；③从句前有插入语；④两个并列 that 从句中的第二个；⑤从句主语是 this/that 或被 this/that 修饰。主句是过去时，从句时态要相应用过去相关时态。</p><p>正例：I think it necessary that we take plenty of hot water every day.；I agree with what you said just now.（介词宾语从句）；I am happy that you can join us.（形容词后的宾语从句）；She said she would visit her grandparents the next week.（主句过去时 → 从句过去将来时） 反例：I find it necessary we practice English every day. ×（该句型里的 that 不能省略）；They are talking about if they should accept the offer. ×（介词后只用 whether）；She said she will visit her grandparents the next week. ×（主句过去时，从句要用 would） 适用边界：主语是过去时（said/asked）时，从句时态要相应过去化（will → would）；从句表示客观真理时仍用一般现在时。it 作形式宾语只在 think/find/consider/believe/make 等动词后带形容词补语时使用。</p><p><strong>口诀</strong>：it + 形容词 + that 是固定语序，that 不能省 —— think/find/consider/believe 后面一旦出现 it，语序只能是 it + adj. + that，其余排列都不成立。</p></div><div class="hint-container tip"><p class="hint-container-title">whether 与 if 的七种区别</p><p><strong>句意</strong>：Juliet has gone to Milan and I wonder whether she can make it to our wedding or not. 意思是“朱丽叶去了米兰，我想知道她能不能赶上我们的婚礼”。</p><p><strong>拆解</strong></p><ul><li>wonder 后面是宾语从句，从句意思是“能不能赶上”</li><li>从句与 or not 连用 → 只能用 whether，不能用 if</li><li>tell、ask、know、wonder、doubt 后的“是否”在口语里可以用 if，但下面七种情况一律用 whether</li><li>七种情况：①discuss/decide/doubt 后 ②whether or not ③从句在句首 ④介词后 ⑤含义易混时 ⑥whether to do ⑦引导主/表/同位语从句</li></ul><p><strong>语法</strong>：whether 可以引导所有名词性从句；if 只能引导宾语从句表“是否”，多见于 ask、know、wonder、doubt 等动词后的口语语境。</p><p>正例：I wonder whether she can make it to our wedding or not.；We discussed whether we should go there by plane.；They are talking about whether he will win the game.（介词后）；Whether the football game will be played depends on the weather.（主语从句） 反例：I wonder if she can make it to our wedding or not. ×（与 or not 连用要用 whether）；They are talking about if he will win the game. ×（介词后只用 whether）；If the football game will be played depends on the weather. ×（if 不能引导主语从句） 适用边界：if 只在“宾语从句 + 表是否”时可用，且多见于 ask、know、wonder、doubt 后的口语语境；从句一旦跑到句首、介词后或主/表/同位语位置，就只能用 whether。</p><p><strong>口诀</strong>：介前、句首、to do、or not、讨论决定怀疑、主表同位——都只能 whether —— 记六组关键词：介词后、从句在句首、whether to do、与 or not 连用、discuss/decide/doubt 后、主语/表语/同位语从句。</p></div><div class="hint-container tip"><p class="hint-container-title">否定转移与 -ever 类引导词：whoever = anyone who</p><p><strong>句意</strong>：I don&#39;t think he is right. 意思是“我认为他不对”；The police decide to question whoever comes along on this road. 意思是“警方决定盘问所有出现在这条路上的人”。</p><p><strong>拆解</strong></p><ul><li>第一句：否定词 not 本属于从句（he is not right），英语习惯把它转移到主句 → I don&#39;t think he is right.</li><li>对应的反意疑问句用肯定：I don&#39;t think he is right, is he?</li><li>第二句：whoever 引导宾语从句，并在从句里作主语（comes 前缺主语），等于 anyone who</li><li>区别：whoever 表泛指（无论谁、任何……的人），who 常表特指（哪一个谁）；give a child whatever he or she wants 里的 whatever = anything that</li></ul><p><strong>语法</strong>：think/believe/suppose/expect 等表观点的动词作主句谓语时，从句否定常转移至主句。whoever = anyone who、whatever = anything that、whichever = any one that 表泛指；从句缺主语时用 whoever，不能用 whomever。</p><p>正例：I don&#39;t think he is right.（= I think he is not right.）；I don&#39;t believe she will come.（我认为她不会来。）；The police decide to question whoever comes along on this road.；It is generally considered unwise to give a child whatever he or she wants. 反例：question whomever comes along ×（从句缺主语，whomever 只能作宾语）；I hope not like think：用 I don&#39;t hope… 表示“我希望不” ×（hope 不参与否定转移，要说 I hope not） 适用边界：否定转移只发生在 think/believe/suppose/expect 等表观点的动词后；hope 不转移（不说 I don t hope…，要说 I hope not）。whoever 表泛指、who 表特指；从句缺主语时不能用 whomever。</p><p><strong>口诀</strong>：观点动词否在前，附加问句反着来 —— not 提到主句后，反意疑问句要用肯定形式（is he?），因为否定已经在主句里用掉了。</p></div><table><thead><tr><th>句型</th><th>例句</th></tr></thead><tbody><tr><td>It is + <strong>名词</strong> + 从句</td><td>It is a fact <strong>that</strong> the earth goes round the sun.</td></tr><tr><td>It is + <strong>形容词</strong> + that</td><td>It is doubtful <strong>that</strong> safety is the real goal.</td></tr><tr><td>It is + <strong>分词</strong> + that</td><td>It is reported <strong>that</strong> she will go abroad soon.</td></tr><tr><td>It + <strong>不及物动词</strong>（happen, doesn&#39;t matter...）+ that</td><td>It happened <strong>that</strong> I saw her three days ago.</td></tr></tbody></table><p>It is/was said/reported/believed/estimated...that... = sb./sth. be + said/reported/believed/estimated to do（据说/据报道/据信/据估计……）。</p><h2 id="第四部分-·-宾语从句-教材-p119–120" tabindex="-1"><a class="header-anchor" href="#第四部分-·-宾语从句-教材-p119–120"><span>第四部分 · 宾语从句（教材 P119–120）</span></a></h2><p>置于<strong>动词、介词</strong>后起宾语作用的从句。三类：</p><ul><li><strong>动词</strong>宾语从句：We believe <strong>that he is honest</strong>. 我们相信他是诚实的。</li><li><strong>介词</strong>宾语从句：I agree with <strong>what you said just now</strong>. 我同意你刚才说的话。</li><li><strong>形容词</strong>宾语从句：I am happy <strong>that you can join us</strong>. 你能加入我们，我很高兴。</li></ul><h3 id="_1-that-引导的宾语从句" tabindex="-1"><a class="header-anchor" href="#_1-that-引导的宾语从句"><span>1. that 引导的宾语从句</span></a></h3><p>that 不作成分、无实际意义，只起连接作用，<strong>口语和非正式文体中可省略</strong>。但以下 5 种情况不能省略：</p><div class="hint-container caution"><p class="hint-container-title">易错</p><p>that 不能省略</p><ol><li><p><strong>find/believe/think/consider/make + it + adj. + that 宾从</strong>句型中不省略：I think <strong>it</strong> necessary <strong>that</strong> we take plenty of hot water every day.</p></li><li><p>宾语从句是<strong>双宾语中的直接宾语</strong>时：I want to tell you <strong>that</strong> this problem is very common.</p></li><li><p>宾语从句前有<strong>插入语</strong>时：We hope, on the contrary, <strong>that</strong> he will stay at home with us.</p></li><li><p>两个或以上并列的 that 宾从：<strong>第一个可省，其余不省</strong>：He said (that) the book was very interesting and <strong>that</strong> all the children like to read it.</p></li><li><p>宾语从句的主语是 <strong>this/that</strong> 或被 this/that 修饰时：The teacher said <strong>that</strong> <strong>that</strong> word was wrong.</p></li></ol></div><h3 id="_2-用-whether-不用-if-的-7-种情况" tabindex="-1"><a class="header-anchor" href="#_2-用-whether-不用-if-的-7-种情况"><span>2. 用 whether 不用 if 的 7 种情况</span></a></h3><div class="hint-container info"><p class="hint-container-title">本节指引 · 第五部分 · 表语从句（教材 P121+123）</p><ul><li><strong>目标</strong>：解决“系动词后面和抽象名词后面的从句怎么选引导词”：表语从句抓住 reason → that 与 because/why 的方向差别，同位语从句抓住抽象名词 + that 不省，并用“that 作不作成分”与定语从句划清界线。</li><li><strong>建议用时</strong>：15 分钟</li><li><strong>知识点</strong>：<code>表语从句与 reason 后的 that</code> <code>同位语从句与抽象名词</code></li></ul></div><h3 id="第五部分-·-表语从句-教材-p121-123-·-小步学" tabindex="-1"><a class="header-anchor" href="#第五部分-·-表语从句-教材-p121-123-·-小步学"><span>第五部分 · 表语从句（教材 P121+123） · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>名词性从句：把一件事放进句子</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>表语从句：reason 后面用 that，不用 because</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>表语从句缺宾语：The problem is what he said at the meeting.</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>同位语从句与定语从句的分水岭：that 作不作成分</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：用一句话说出 because 与 why 在表语从句里的方向区别，再说出判断同位语从句与定语从句的那一招。</p><div class="hint-container tip"><p class="hint-container-title">表语从句：reason 后面用 that，不用 because</p><p><strong>句意</strong>：The reason for his absence is that he missed the early bus. 意思是“他缺席的原因是他错过了早班公交车”。</p><p><strong>拆解</strong></p><ul><li>The reason for his absence 是主句主语，is 是系动词</li><li>that he missed the early bus 是表语从句：从句主语、谓语、宾语齐全 → that 只连接、不作成分</li><li>主语是 reason 时，表语从句不能用 because（The reason is because… ×）</li><li>同理：The reason why I didn&#39;t attend the lecture that day was simply that I got a bad cold.</li></ul><p><strong>语法</strong>：表语从句放在系动词之后，引导词含一般引导词 + why + because + as though/if。三组固定结构：This/That/It is because…（那是因为，后接原因）；This/That/It is why…（那就是……的原因，后接结果）；主语为 reason 时，连接词用 that。</p><p>正例：The reason for his absence is that he missed the early bus.；He was late. That was because he was caught in a traffic jam.；He was caught in a traffic jam. That was why he was late. 反例：The reason for his absence is because he missed the early bus. ×（reason 作主语 → that）；That was why he was caught in a traffic jam. ×（表意颠倒：why 后接结果，because 后接原因） 适用边界：because 与 why 方向相反，只能靠语境判断：先说结果 → That is why…；先给结果再解释原因 → That is because…。主语是 reason 时不能用 because。</p><p><strong>口诀</strong>：reason → that；That is because 后接原因，That is why 后接结果 —— because 与 why 方向相反，先问“后面那句讲的是原因还是结果”。</p></div><div class="hint-container tip"><p class="hint-container-title">表语从句缺宾语：The problem is what he said at the meeting.</p><p><strong>句意</strong>：The problem is what he said at the meeting yesterday. 意思是“问题是他昨天在会上说了什么”。</p><p><strong>拆解</strong></p><ul><li>The problem 是主句主语，is 是系动词</li><li>从句 he said ____ at the meeting yesterday 里 said 缺宾语 → 用连接代词 what</li><li>what 既连接从句又作 said 的宾语，译“什么”</li><li>对比：The most important thing is not what you do, but how you do it.（第一空缺宾语用 what，第二空完整、有含义用 how）</li></ul><p><strong>语法</strong>：表语从句同样遵循“从句缺成分用连接代词、不缺成分用 that/whether/四条大何”的规则。when/where/why/how 作表语从句引导词时各自保留含义（时刻、地点、原因、方式），如 My happiest moment is when I attended my best friend&#39;s wedding.；It&#39;s where the glass is beyond the reach of our children.</p><p>正例：The problem is what he said at the meeting yesterday.；The most important thing is not what you do, but how you do it.；It&#39;s where the glass is beyond the reach of our children.；My happiest moment is when I attended my best friend&#39;s wedding. 反例：The problem is that he said at the meeting yesterday. ×（said 缺宾语，that 不作成分）；The problem is which he said at the meeting yesterday. ×（which 表“哪一个”，需要选择范围） 适用边界：when/where/why/how 作表语从句引导词时仍保留各自含义（时刻、地点、原因、方式）；只要从句缺主语或宾语，就必须换成连接代词。</p><p><strong>口诀</strong>：从句缺宾语用 what，不缺成分才轮到 when/where/how —— 把从句单独读一遍，看 said、do 这类及物动词后面有没有宾语。</p></div><div class="hint-container tip"><p class="hint-container-title">同位语从句与定语从句的分水岭：that 作不作成分</p><p><strong>句意</strong>：The suggestion that the students should have plenty of exercise is very good. 意思是“学生应当多做锻炼这个建议很好”。</p><p><strong>拆解</strong></p><ul><li>The suggestion 是抽象名词，that the students should have plenty of exercise 说明建议的具体内容 → 同位语从句</li><li>从句主语 the students、谓语 should have、宾语 exercise 齐全，that 不作成分、不可省略</li><li>改成 The suggestion that he raised at the meeting is very good.：raised 缺宾语，that 作宾语 → 定语从句（作宾语时还可省略）</li><li>同位语从句的常见先行名词：idea、fact、news、hope、belief、thought、doubt、promise、suggestion、order、possibility</li></ul><p><strong>语法</strong>：同位语从句跟在抽象名词后说明其内容，that 不作成分、不可省略；定语从句里的 that 是关系代词，充当成分（作宾语时可省略）。用 whether/where/how 等也能引导同位语从句：The student asked me the question whether the book was worth reading.</p><p>正例：The news that our team had won the game spread quickly.；There is an idea that too much stress can partly cause the disease.；Along with the letter was his promise that he would visit me this coming Christmas. 反例：把 The suggestion that he raised at the meeting 说成同位语从句 ×（that 作 raised 的宾语 → 定语从句）；把 The news that our team had won the game 说成定语从句 ×（从句完整、that 不作成分 → 同位语从句） 适用边界：判断口诀：拿掉 that 看从句是否完整——完整说明 that 不作成分（同位语从句），不完整说明 that 充当成分（定语从句）。同位语从句的 that 不可省略。</p><p><strong>口诀</strong>：拿掉 that 读一读：完整是同位语，缺成分是定语从句 —— 两者都紧跟名词、都常译“……的”，最容易混，用“that 作不作成分”一招分清楚。</p></div><p><strong>whether</strong> 可以引导<strong>所有</strong>名词性从句；<strong>if</strong> 只能引导<strong>宾语从句</strong>表&quot;是否&quot;，多见于口语或非正式语境（常见于 ask、know、wonder、doubt 等动词后）：</p><ol><li>动词 <strong>discuss, decide, doubt</strong> 后：We discussed <strong>whether</strong> we should go there by plane.</li><li><strong>whether or not</strong> 结构中：Let me know <strong>whether</strong> you can come or not.</li><li>宾语从句<strong>置于句首</strong>时：<strong>Whether</strong> it is true or not, I can&#39;t tell. 这是不是真的，我无法判断。</li><li><strong>介词后</strong>：They are talking about <strong>whether</strong> he will win the game.</li><li>whether 与 if 含义易混时：Please let me know <strong>whether</strong> you want to go.</li><li><strong>whether to do</strong>：I can&#39;t decide <strong>whether to stay</strong>.</li><li>引导<strong>主语从句、表语从句、同位语从句</strong>时：<strong>Whether</strong> the football game will be played depends on the weather.</li></ol><h2 id="第五部分-·-表语从句-教材-p121-123" tabindex="-1"><a class="header-anchor" href="#第五部分-·-表语从句-教材-p121-123"><span>第五部分 · 表语从句（教材 P121+123）</span></a></h2><p>置于<strong>系动词后</strong>起表语作用的从句。引导词：除 if 外的一般引导词 + why + because + as though/if。</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>三组固定结构</p><ol><li><p><strong>This/That/It is/was because...</strong>：那是因为……He was late. <strong>That was because</strong> he was caught in a traffic jam. 那是因为他遇上了堵车。</p></li><li><p><strong>This/That/It is/was why...</strong>：那就是……的原因He was caught in a traffic jam. <strong>That was why</strong> he was late. 那就是他迟到的原因。</p></li><li><p>主语为 <strong>reason</strong> 时，表语从句连接词用 <strong>that</strong>：The reason was <strong>that</strong> he was caught in a traffic jam.</p></li></ol></div><h2 id="第六部分-·-同位语从句-教材-p123" tabindex="-1"><a class="header-anchor" href="#第六部分-·-同位语从句-教材-p123"><span>第六部分 · 同位语从句（教材 P123）</span></a></h2><p>作某一<strong>抽象名词</strong>的同位语，一般位于该名词之后，<strong>解释和说明该名词的具体内容</strong>。常见名词：<strong>idea</strong>（主意）、<strong>fact</strong>（事实）、<strong>news</strong>（新闻）、<strong>hope</strong>（希望）、<strong>belief</strong>（信念）、<strong>thought</strong>（想法）、<strong>doubt</strong>（怀疑）、<strong>promise</strong>（承诺）、<strong>suggestion</strong>（建议）、<strong>order</strong>（命令）、<strong>possibility</strong>（可能）等。</p><p><strong>引导词</strong>：<strong>that</strong>（无实义，<strong>不可省略</strong>）；when、where、why、how、whether 等。</p><p>Some people have the idea <strong>that you can cross Canada in less than five days</strong>. 有人认为穿越加拿大只需要不到五天。 The student asked me the question <strong>whether the book was worth reading</strong>. 学生问我这本书是否值得阅读。</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>同位语从句 vs 定语从句 <strong>定语从句</strong>：that 是关系代词，<strong>充当句子成分</strong>，作宾语时可省略；<strong>同位语从句</strong>：that 是连词，<strong>不充当成分</strong>，一般不可省略。</p><p>The suggestion <strong>that he raised at the meeting</strong> is very good.（that 作 raised 的宾语 → <strong>定语从句</strong>） The suggestion <strong>that the students should have plenty of exercise</strong> is very good.（that 不作成分，说明 suggestion 内容 → <strong>同位语从句</strong>）</p></div><h2 id="第七部分-·-宾语从句中的否定转移-导图专题补充" tabindex="-1"><a class="header-anchor" href="#第七部分-·-宾语从句中的否定转移-导图专题补充"><span>第七部分 · 宾语从句中的否定转移（导图专题补充）</span></a></h2><p>当主句谓语是 <strong>think / believe / suppose / expect</strong> 等表观点的动词时，否定<strong>从句</strong>的 not 通常<strong>转移到主句</strong>：</p><p>I <strong>don&#39;t think</strong> he <strong>is</strong> right.（= I think he is not right. 我认为他不对。） I <strong>don&#39;t believe</strong> she <strong>will come</strong>.（我认为她不会来。）</p><p>反意疑问句与之配合：I don&#39;t think he is right, <strong>is he</strong>?（陈述部分否定已前移，附加问句用肯定）</p><h2 id="易错清单" tabindex="-1"><a class="header-anchor" href="#易错清单"><span>易错清单</span></a></h2><div class="hint-container caution"><p class="hint-container-title">易错</p><p>高频易错</p><ol><li><p><strong>if 与 whether 七区别</strong>：介词后、句首、to do、or not 连用、discuss/decide/doubt 后、主/表/同位语从句——全用 whether</p></li><li><p><strong>名词性从句一律用陈述语序</strong>（Could you tell me how you... ✘ how do you）</p></li><li><p><strong>reason 作主语，表语从句用 that</strong>，不用 because（The reason is that...）</p></li><li><p><strong>That is because</strong>（那是因为，后接原因）/ <strong>That is why</strong>（那就是为什么，后接结果）方向相反</p></li><li><p><strong>同位语从句 vs 定语从句</strong>：that 作不作成分；同位语 that 不可省</p></li><li><p><strong>it 作形式主语/形式宾语</strong>：think it necessary that...；It is reported that... = sb. is reported to do</p></li><li><p><strong>What...is that...</strong> 主语从句缺主语用 What；<strong>As 不能单独引导主语从句作主语</strong>（需逗号非限或 It is known that）</p></li><li><p><strong>whoever = anyone who</strong>（泛指）≠ who（特指）</p></li></ol></div><h2 id="课堂练习" tabindex="-1"><a class="header-anchor" href="#课堂练习"><span>课堂练习</span></a></h2><p><strong>Excuse me, can you show me ____ you operate the machine?</strong></p><ul><li>A. what</li><li>B. which</li><li>C. how</li><li>D. who</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（how）</strong> —— 从句不缺主要成分，删掉引导词含义不完整（&quot;如何操作&quot;）→ 用有含义的 how。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ what 要在从句里作主语或宾语，而 you operate the machine 主语、谓语、宾语齐全，what 没有位置。干扰点：只想着“告诉他什么”，忽略了从句其实完整。</li><li>B ❌ which 表“哪一个”，需要选择范围；本句没有供选择的几台机器，也不要求“哪一个”。</li><li>C ✅ 宾语从句 you operate the machine 不缺主要成分，但删掉引导词后含义不完整（“如何操作”）→ 用有含义的连接副词 how。</li><li>D ❌ who 要在从句里作主语或宾语、而且指人；本句从句主语是 you，不缺口。</li></ul><p><strong>整句翻译</strong>：打扰一下，你能告诉我怎样操作这台机器吗？</p><p><strong>词组</strong>：<code>show sb. sth.</code> 给某人看某物；告诉某人某事；<code>operate the machine</code> 操作机器</p><p><strong>对比自测</strong>：做完后对照 quiz:17，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第二部分 · 四步解题法）：③ 看成分：从句缺主语/宾语/定语 → 从“作成分”的 5W 中选；不缺成分 → 从“不作成分”三类中选 ④ 看含义</p></details><p><strong>The news ____ our athletes won another gold medal was reported in yesterday’s newspaper.</strong></p><ul><li>A. which</li><li>B. if</li><li>C. what</li><li>D. that</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（that）</strong> —— 同位语从句：从句不缺成分、无含义 → that（if 不能引导同位语从句）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 从句 our athletes won another gold medal 完整，which 没有位置；说明 news 的内容时也不用 which。干扰点：见到名词后紧跟从句就当定语从句。</li><li>B ❌ if 不能引导同位语从句（表“是否”时要用 whether），本句也不是“是否”的含义。</li><li>C ❌ what 要在从句里作成分，而本句从句完整，不需要补成分。</li><li>D ✅ the news 是抽象名词，后面的从句说明“消息的内容”→ 同位语从句；从句完整、无含义 → 用 that，且不可省略。</li></ul><p><strong>整句翻译</strong>：我们的运动员又赢得一枚金牌的消息刊登在昨天的报纸上。</p><p><strong>词组</strong>：<code>win another gold medal</code> 再赢得一枚金牌；<code>be reported</code> 被报道、被刊登</p><p><strong>对比自测</strong>：做完后对照 quiz:26，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第六部分 · 同位语从句）：引导词：that（无实义，不可省略）；when、where、why、how、whether 等</p></details><p><strong>____ surprised all of us was that he canceled the meeting.</strong></p><ul><li>A. Which</li><li>B. What</li><li>C. It</li><li>D. That</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（What）</strong> —— 主语从句缺主语 → What。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ which 表“哪一个”，需要有选择范围；本句不是“哪一个最让人吃惊”。</li><li>B ✅ 主语从句 ____ surprised all of us 里 surprised 前缺主语 → 用连接代词 what（在从句中作主语）。</li><li>C ❌ It 是代词，不能连接后面的 was；若用形式主语，句子该写成 It surprised all of us that he canceled the meeting.</li><li>D ❌ that 不作成分、要求从句完整，而 surprised 前缺主语，从句不完整。干扰点：只记住“主语从句可以用 that”。</li></ul><p><strong>整句翻译</strong>：让我们所有人吃惊的是他竟然取消了会议。</p><p><strong>词组</strong>：<code>cancel a meeting</code> 取消会议；<code>all of us</code> 我们所有人</p><p><strong>对比自测</strong>：做完后对照 quiz:6，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第二部分 · 5 个 W）：what：作主语、宾语，含义“什么（物）”</p></details><p><strong>【22重庆真题改编】____ makes me feel surprised is that he made such a success.</strong></p><ul><li>A. It</li><li>B. That</li><li>C. What</li><li>D. Which</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（What）</strong> —— 主语从句缺主语（makes 前没有主语）→ What；That 不作成分但需从句完整。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ It makes me feel surprised 本身已是完整句子，无法再接后面的 is that…；形式主语要写成 It is surprising that…。</li><li>B ❌ makes 前缺主语，从句不完整 → 不能用 that。干扰点：把 that 当成“主语从句万能引导词”。</li><li>C ✅ 主语从句 ____ makes me feel surprised 里 makes 前缺主语 → 用连接代词 what。</li><li>D ❌ which 需要选择范围，本句没有“哪一个”的选择。</li></ul><p><strong>整句翻译</strong>：让我感到吃惊的是他竟然取得了这样的成功。</p><p><strong>词组</strong>：<code>make sb. feel surprised</code> 让某人感到吃惊；<code>make such a success</code> 取得这样的成功</p><p><strong>对比自测</strong>：做完后对照 quiz:4，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第二部分 · 小结）：当名词性从句中不缺成分时，可以用 that / whether / 四条大何；缺成分时用连接代词</p></details><p><strong>【22重庆】____ I can’t understand is ____ he wants to change his mind.</strong></p><ul><li>A. That; that</li><li>B. Which; what</li><li>C. What; that</li><li>D. What; why</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（What; that）</strong> —— 第一空 understand 缺宾语 → What；第二空从句完整 → that。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 第一空：从句 I can&#39;t understand 里 understand 缺宾语，that 不作成分 → 不能用 That。干扰点：以为主语从句一律用 That 开头。</li><li>B ❌ 第一空：which 表“哪一个”且要有范围；第二空：从句 he wants to change his mind 完整，what 没有位置。</li><li>C ✅ 第一空 understand 缺宾语 → What；第二空表语从句完整、无含义 → that。</li><li>D ❌ 第一空对；第二空从句完整，应用 that，why 表“为什么”与句意不符。干扰点：看到“为什么”就觉得该用 why。</li></ul><p><strong>整句翻译</strong>：我不能理解的是他竟然想改变主意。</p><p><strong>词组</strong>：<code>change one&#39;s mind</code> 改变主意；<code>What … is that …</code> ……的是……（前空缺成分用 What，后空完整用 that）</p><p><strong>对比自测</strong>：做完后对照 quiz:37，比较两题的判断依据</p><p><strong>原文定位</strong>（课件易错清单）：What…is that… 主语从句缺主语用 What</p></details><p><strong>____ the team will win the championship depends on their performance in the final.</strong></p><ul><li>A. That</li><li>B. Whether</li><li>C. If</li><li>D. What</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（Whether）</strong> —— 主语从句表&quot;是否&quot;用 Whether；if 不能引导主语从句。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ that 无含义，句子就成了“队伍会赢得冠军取决于……”，与“能否、是否”的语义不符。</li><li>B ✅ 主语从句表“是否” → 用 whether；whether 能引导包括主语从句在内的所有名词性从句。</li><li>C ❌ if 不能引导主语从句。干扰点：把汉语的“是否”一律翻成 if。</li><li>D ❌ what 要在从句里作成分，而 the team will win the championship 主语、谓语、宾语齐全。</li></ul><p><strong>整句翻译</strong>：这支队伍能否赢得冠军取决于他们在决赛中的表现。</p><p><strong>词组</strong>：<code>win the championship</code> 赢得冠军；<code>depend on</code> 取决于、依靠</p><p><strong>对比自测</strong>：做完后对照 quiz:11，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第四部分 · 用 whether 不用 if 的 7 种情况）：引导主语从句、表语从句、同位语从句时：Whether the football game will be played depends on the weather.</p></details><p><strong>____ surprised us most was his sudden decision to quit the job.</strong></p><ul><li>A. That</li><li>B. Which</li><li>C. What</li><li>D. It</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（What）</strong> —— 从句缺主语 → What。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ surprised 前缺主语，从句不完整 → 不能用 that。干扰点：只注意“主语从句可以用 that”。</li><li>B ❌ which 表“哪一个”，需要选择范围，本句没有。</li><li>C ✅ 主语从句 ____ surprised us most 里 surprised 前缺主语 → 用连接代词 what。</li><li>D ❌ It 不能连接后面的 was；若用形式主语应写成 It surprised us most that he made a sudden decision to quit the job.</li></ul><p><strong>整句翻译</strong>：最让我们吃惊的是他突然决定辞职。</p><p><strong>词组</strong>：<code>quit the job</code> 辞职；<code>a sudden decision</code> 突然的决定</p><p><strong>对比自测</strong>：做完后对照 quiz:2，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第二部分 · 5 个 W 表格）：what：所作成分为主、宾，含义“什么（物）”；who：主语；whom：宾语；which/whose：定语</p></details><p><strong>____ is important that we should protect the environment.</strong></p><ul><li>A. What</li><li>B. This</li><li>C. It</li><li>D. That</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（It）</strong> —— It 作形式主语（It is important that...）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ what 要在从句里作成分；本句真正的主语是后面的 that 从句，用 What 会造成重复。</li><li>B ❌ This 不能作形式主语，英语里形式主语只用 it。干扰点：按汉语“这很重要”直译。</li><li>C ✅ It 作形式主语，先占住主语位置，真正的主语是后面的 that we should protect the environment。</li><li>D ❌ 填 That 会构成主语从句 That we should protect the environment，后面又多出 is important，结构重复。</li></ul><p><strong>整句翻译</strong>：我们应当保护环境，这一点很重要。</p><p><strong>词组</strong>：<code>protect the environment</code> 保护环境</p><p><strong>对比自测</strong>：做完后对照 quiz:38，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第三部分 · 形式主语）：It is + 形容词 + that：It is doubtful that safety is the real goal.</p></details><p><strong>____ we can solve the problem efficiently requires careful discussion.</strong></p><ul><li>A. How</li><li>B. That</li><li>C. What</li><li>D. Which</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（How）</strong> —— 从句不缺主要成分，&quot;如何高效解决&quot;有含义 → How。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 从句 we can solve the problem efficiently 主语、谓语、宾语齐全，缺的是“如何”的方式含义 → 用 how。</li><li>B ❌ 从句完整可以用 that 连接，但 that 无含义，句子就丢了“如何解决”这层意思，语义不成立。</li><li>C ❌ solve 的宾语是 the problem，从句不缺宾语，what 没有位置。</li><li>D ❌ which 表“哪一个”，需要选择范围。</li></ul><p><strong>整句翻译</strong>：我们如何高效地解决这个问题需要认真讨论。</p><p><strong>词组</strong>：<code>solve the problem</code> 解决问题；<code>careful discussion</code> 认真讨论</p><p><strong>对比自测</strong>：做完后对照 quiz:16，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第二部分 · 四条大何）：连接副词 when / where / why / how：不作主要成分，有含义</p></details><p><strong>____ he often forgot their wedding anniversary greatly annoyed his wife.</strong></p><ul><li>A. All</li><li>B. What</li><li>C. Which</li><li>D. That</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（That）</strong> —— 从句完整、引导词无含义 → That。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ All 是代词，后面要接 that 从句（All that he…）才能作主语，不能直接跟完整从句。</li><li>B ❌ 从句 he often forgot their wedding anniversary 主语、谓语、宾语齐全，what 没有位置。干扰点：一看到长长的从句就想到 what。</li><li>C ❌ which 表“哪一个”，需要有选择范围。</li><li>D ✅ 主语从句完整、引导词无含义 → 用 that，构成 That he often forgot their wedding anniversary 作主语。</li></ul><p><strong>整句翻译</strong>：他常常忘记他们的结婚纪念日，这让他妻子非常恼火。</p><p><strong>词组</strong>：<code>wedding anniversary</code> 结婚纪念日；<code>annoy sb.</code> 使某人恼火</p><p><strong>对比自测</strong>：做完后对照 quiz:8，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第二部分 · that）：that：不作成分；无含义：That he misspelled the word made everyone happy.</p></details><p><strong>____ I am trying to do is to persuade my elder brother to give up smoking.</strong></p><ul><li>A. That</li><li>B. When</li><li>C. What</li><li>D. Which</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（What）</strong> —— do 缺宾语 → What。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ do 后面缺宾语，从句不完整 → that 不作成分，不能填。干扰点：只记“主语从句用 That”。</li><li>B ❌ when 只作时间状语，而从句缺的是 do 的宾语。</li><li>C ✅ 主语从句 ____ I am trying to do 里 do 缺宾语 → 用连接代词 what。</li><li>D ❌ which 表“哪一个”，需要选择范围。</li></ul><p><strong>整句翻译</strong>：我想要做的是说服我哥哥戒烟。</p><p><strong>词组</strong>：<code>persuade sb. to do sth.</code> 说服某人做某事；<code>give up smoking</code> 戒烟</p><p><strong>对比自测</strong>：做完后对照 quiz:4，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第二部分 · 5 个 W 表格）：what：所作成分为主、宾，含义“什么（物）”；（What I am trying to do is to persuade… 中 what 作 do 的宾语）</p></details><p><strong>____ we can succeed or not depends on how well we cooperate with others.</strong></p><ul><li>A. Then</li><li>B. Thus</li><li>C. What</li><li>D. Whether</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（Whether）</strong> —— Whether...or not 引导主语从句。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ then 是副词，不能引导从句。</li><li>B ❌ thus 是副词，不能引导从句。</li><li>C ❌ what 要在从句里作成分，而 we can succeed 完整；or not 也提示含义是“是否”。</li><li>D ✅ Whether … or not 引导主语从句，表示“是否”。</li></ul><p><strong>整句翻译</strong>：我们能否成功取决于我们与他人合作得有多好。</p><p><strong>词组</strong>：<code>cooperate with sb.</code> 与某人合作；<code>or not</code> 是否（与 whether 连用）</p><p><strong>对比自测</strong>：做完后对照 quiz:5，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第四部分 · whether or not 结构）：Let me know whether you can come or not.</p></details><p><strong>They are talking about ____ they should accept the offer.</strong></p><ul><li>A. if</li><li>B. that</li><li>C. whether</li><li>D. what</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（whether）</strong> —— 介词后只用 whether。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 介词 about 后面只能用 whether，不能用 if。干扰点：把汉语的“是否”直接对应 if。</li><li>B ❌ that 无含义，而句中要表达“是否”，用 that 会丢掉疑问含义。</li><li>C ✅ about 是介词，介词后的宾语从句表“是否”→ 只能用 whether。</li><li>D ❌ what 要在从句里作成分，而 they should accept the offer 主语、谓语、宾语齐全。</li></ul><p><strong>整句翻译</strong>：他们正在讨论是否应该接受这个提议。</p><p><strong>词组</strong>：<code>accept the offer</code> 接受提议</p><p><strong>对比自测</strong>：做完后对照 quiz:41，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第四部分 · 介词后）：介词后：They are talking about whether he will win the game.</p></details><p><strong>I find ____ necessary that we practice English every day.</strong></p><ul><li>A. this</li><li>B. it</li><li>C. that</li><li>D. what</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（it）</strong> —— it 作形式宾语（find it necessary that...）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ this 不能作形式宾语；形式宾语只能用 it。</li><li>B ✅ 真正的宾语是 that we practice English every day，前面用 it 作形式宾语，语序是 find + it + necessary + that 从句。</li><li>C ❌ 填 that 会变成 find that necessary…，而正确语序是 it + 形容词 + that。干扰点：把 that 从句当成需要的成分直接塞进空里。</li><li>D ❌ what 要在从句里作成分；本句真正的宾语是 that 从句，what 无处可放。</li></ul><p><strong>整句翻译</strong>：我发现我们每天练习英语是必要的。</p><p><strong>词组</strong>：<code>practice English</code> 练习英语；<code>find it + adj. + that</code> 发现……是……的（it 作形式宾语）</p><p><strong>对比自测</strong>：做完后对照 quiz:42，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第四部分 · that 不能省略）：find/believe/think/consider/make + it + adj. + that 宾从：I think it necessary that we take plenty of hot water every day.</p></details><p><strong>He asked me ____ would attend the party with him.</strong></p><ul><li>A. whom</li><li>B. which</li><li>C. who</li><li>D. whose</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（who）</strong> —— 从句缺主语且指人 → who。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 从句 ____ would attend the party with him 里 would attend 前缺主语，whom 只能作宾语。</li><li>B ❌ which 表“哪一个”，需要选择范围；这里问的是“谁”。</li><li>C ✅ 从句缺主语且指人 → 用 who。</li><li>D ❌ whose 后面必须紧跟名词作定语，本句没有“谁的 + 名词”。</li></ul><p><strong>整句翻译</strong>：他问我谁会和他一起参加聚会。</p><p><strong>词组</strong>：<code>attend the party</code> 参加聚会；<code>with him</code> 和他一起</p><p><strong>对比自测</strong>：做完后对照 quiz:43，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第二部分 · 5 个 W 表格）：who：所作成分为主语，含义“谁”；whom：所作成分为宾语，含义“谁”</p></details><p><strong>She said she ____ visit her grandparents the next week.</strong></p><ul><li>A. will</li><li>B. would</li><li>C. is going to</li><li>D. has</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（would）</strong> —— 主句 said 是过去时，the next week 提示过去将来时 → would。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 主句 said 是过去时，从句时态要相应过去化，不能用 will。干扰点：只按汉语“她下周会去”直译。</li><li>B ✅ 主句是过去时，the next week 表示“从过去看将来”→ 从句用过去将来时 would。</li><li>C ❌ is going to 是现在时的语态，与主句 said 的过去语境不一致。</li><li>D ❌ has 是现在完成时的助动词，既不表示将来，也与过去语境不符。</li></ul><p><strong>整句翻译</strong>：她说她下周会去看望她的祖父母。</p><p><strong>词组</strong>：<code>the next week</code> （站在过去看的）第二周、下周（宾语从句里表示将来）；<code>visit one&#39;s grandparents</code> 看望祖父母</p><p><strong>对比自测</strong>：做完后对照 quiz:0，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第四部分 · 宾语从句）：We believe that he is honest. 我们相信他是诚实的。（主句时态与从句时态呼应）</p></details><p><strong>This story is about ____ a boy managed to save a little girl in the earthquake.</strong></p><ul><li>A. how</li><li>B. what</li><li>C. which</li><li>D. that</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（how）</strong> —— &quot;如何成功救出&quot;有含义 → how。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ about 是介词，后面是宾语从句；从句 a boy managed to save a little girl 完整，需要“如何救出”这层含义 → how。</li><li>B ❌ managed 的宾语是 to save a little girl，从句不缺宾语，what 没有位置。</li><li>C ❌ which 表“哪一个”，需要选择范围。</li><li>D ❌ 从句完整可以用 that 连接，但 that 无含义，句子就丢了“如何救出”的意思，语义不完整。</li></ul><p><strong>整句翻译</strong>：这个故事讲的是一个男孩在地震中如何设法救出一个小女孩。</p><p><strong>词组</strong>：<code>manage to do sth.</code> 设法做成某事；<code>in the earthquake</code> 在地震中</p><p><strong>对比自测</strong>：做完后对照 quiz:17，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第四部分 · 介词宾语从句）：I agree with what you said just now.（介词后的从句同样按“缺不缺成分”选引导词）</p></details><p><strong>I wonder ____ Mary has kept her figure over the years.</strong></p><ul><li>A. how</li><li>B. that</li><li>C. when</li><li>D. what</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（how）</strong> —— &quot;这些年如何保持身材&quot; → how。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 从句 Mary has kept her figure over the years 主语、谓语、宾语齐全，含义是“如何保持” → how。</li><li>B ❌ that 无含义，句子就丢了“如何保持”的意思；wonder 也需要疑问含义。</li><li>C ❌ when 表时间，而 over the years 已经在从句里充当时间状语，句意问的是方式。</li><li>D ❌ kept 的宾语是 her figure，从句不缺宾语。</li></ul><p><strong>整句翻译</strong>：我想知道玛丽这些年是如何保持身材的。</p><p><strong>词组</strong>：<code>keep one&#39;s figure</code> 保持身材；<code>over the years</code> 这些年来</p><p><strong>对比自测</strong>：做完后对照 quiz:0，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第二部分 · 小结）：当名词性从句中不缺成分时，可以用 that / whether / 四条大何（when/where/why/how）来引导。</p></details><p><strong>You might keep those old jam bottles. You never know ____ you might need them.</strong></p><ul><li>A. when</li><li>B. that</li><li>C. how</li><li>D. what</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（when）</strong> —— &quot;不知道什么时候会用到&quot; → when。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 从句 you might need them 主语、谓语、宾语齐全，需要“什么时候”这层时间含义 → when。</li><li>B ❌ that 无含义，句子就丢了“什么时候”的意思。</li><li>C ❌ how 表方式，而从句 need 的宾语是 them，句意问的是时间。</li><li>D ❌ need 的宾语是 them，从句不缺宾语，what 没有位置。</li></ul><p><strong>整句翻译</strong>：你也许可以把那些旧果酱瓶留着。你永远不知道什么时候会用到它们。</p><p><strong>词组</strong>：<code>jam bottles</code> 果酱瓶；<code>you never know</code> 你永远不知道（后面常接宾语从句）</p><p><strong>对比自测</strong>：做完后对照 quiz:36，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第二部分 · 四条大何）：He doesn&#39;t know why he can find a girlfriend.（不作主要成分，有含义）</p></details><p><strong>Could you please tell me ____? —Well, I always write e-mails to my pen pals.</strong></p><ul><li>A. how do you learn Chinese</li><li>B. what is your pen pal’s hobby</li><li>C. what do you do after class</li><li>D. how you improve your writing</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（how you improve your writing）</strong> —— 宾语从句用陈述语序排除 A/B/C；答语&quot;总是写邮件&quot; → 怎么提高写作。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ how do you learn Chinese 用了疑问语序（do you），宾语从句必须用陈述语序；答语讲的是写邮件提高写作，也不是学中文。</li><li>B ❌ what is your pen pal&#39;s hobby 是疑问语序（is your）；答语说的是“我”的做法，不是笔友的爱好。</li><li>C ❌ what do you do after class 是疑问语序（do you）；答语讲的是如何提高写作，不是课后活动。</li><li>D ✅ how you improve your writing 是陈述语序（主语 you + 谓语 improve），且与答语“总是写邮件给笔友”对应“如何提高写作”。</li></ul><p><strong>整句翻译</strong>：——你能告诉我你是怎样提高写作的吗？——嗯，我经常给我的笔友写邮件。</p><p><strong>词组</strong>：<code>write e-mails to sb.</code> 给某人写邮件；<code>pen pal</code> 笔友</p><p><strong>对比自测</strong>：做完后对照 quiz:16，比较两题的判断依据</p><p><strong>原文定位</strong>（课件易错清单）：名词性从句一律用陈述语序（Could you tell me how you... ✘ how do you）</p></details><p><strong>The reason for his absence is ____ he missed the early bus.</strong></p><ul><li>A. that</li><li>B. why</li><li>C. because</li><li>D. what</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（that）</strong> —— reason 作主语 → 表语从句用 that，不用 because。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 主语是 The reason，表语从句 he missed the early bus 完整、无含义 → 连接词用 that。</li><li>B ❌ why 表示“为什么”，填进去成了“……的原因是他为什么错过早班车”，语义重复。</li><li>C ❌ 主语是 reason 时，表语从句不能用 because。干扰点：一看到汉语“原因”就选 because。</li><li>D ❌ 从句 he missed the early bus 主语、谓语、宾语齐全，what 没有位置。</li></ul><p><strong>整句翻译</strong>：他缺席的原因是他错过了早班公交车。</p><p><strong>词组</strong>：<code>absence</code> 缺席；<code>miss the early bus</code> 错过早班车</p><p><strong>对比自测</strong>：做完后对照 quiz:22，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第五部分 · 三组固定结构）：主语为 reason 时，表语从句连接词用 that：The reason was that he was caught in a traffic jam.</p></details><p><strong>The problem is ____ he said at the meeting yesterday.</strong></p><ul><li>A. that</li><li>B. what</li><li>C. which</li><li>D. when</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（what）</strong> —— said 缺宾语 → what。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ said 后面缺宾语，从句不完整 → that 不作成分，不能填。干扰点：只记住表语从句常用 that。</li><li>B ✅ 表语从句 he said ____ at the meeting yesterday 里 said 缺宾语 → 用连接代词 what。</li><li>C ❌ which 表“哪一个”，需要选择范围；这里问的是“说了什么”。</li><li>D ❌ when 只作时间状语，而 said 缺的是宾语；yesterday 已经在从句里作时间状语。</li></ul><p><strong>整句翻译</strong>：问题是他昨天在会上说了什么。</p><p><strong>词组</strong>：<code>at the meeting</code> 在会上</p><p><strong>对比自测</strong>：做完后对照 quiz:25，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第二部分 · 5 个 W）：what：作主语、宾语，含义“什么（物）”</p></details><p><strong>The reason why I didn’t attend the lecture that day was simply ____ I got a bad cold.</strong></p><ul><li>A. because</li><li>B. as</li><li>C. that</li><li>D. for</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（that）</strong> —— reason 作主语 → 表语从句用 that。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 主语是 The reason，表语从句不能用 because（The reason … was because … ×）。</li><li>B ❌ as 不引导表语从句；它一般引导时间、原因、方式状语从句或非限制性定语从句。</li><li>C ✅ 主语是 The reason（后面有 why 引导的定语从句修饰），表语从句完整 → 连接词用 that。</li><li>D ❌ for 是介词或并列连词，不能引导表语从句。</li></ul><p><strong>整句翻译</strong>：我那天没去听讲座的原因很简单，就是我得了重感冒。</p><p><strong>词组</strong>：<code>attend the lecture</code> 听讲座；<code>get a bad cold</code> 得了重感冒</p><p><strong>对比自测</strong>：做完后对照 quiz:20，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第五部分 · 三组固定结构）：主语为 reason 时，表语从句连接词用 that：The reason was that he was caught in a traffic jam.</p></details><p><strong>The most important thing is not ____ you do, but ____ you do it.</strong></p><ul><li>A. when; how</li><li>B. what; what</li><li>C. what; how</li><li>D. how; what</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（what; how）</strong> —— 做&quot;什么&quot;用 what；&quot;怎么&quot;做用 how。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 第一空：you do ____ 里 do 缺宾语，when 只作时间状语。</li><li>B ❌ 第一空对；第二空 you do it 完整，what 没有位置。</li><li>C ✅ 第一空 do 缺宾语 → what；第二空 you do it 完整、需要“怎样做”的含义 → how。</li><li>D ❌ 两空与正确答案正好相反：第一空 do 缺宾语不能用 how，第二空完整不能用 what。</li></ul><p><strong>整句翻译</strong>：最重要的不是你做什么，而是你怎样做。</p><p><strong>词组</strong>：<code>the most important thing</code> 最重要的事情；<code>not … but …</code> 不是……而是……</p><p><strong>对比自测</strong>：做完后对照 quiz:21，比较两题的判断依据</p><p><strong>原文定位</strong>（课件易错清单）：缺成分 → 5W 连接代词；不缺成分 → that（无义）/ whether（是否）/ 四条大何（有义）</p></details><p><strong>My happiest moment is ____ I attended my best friend’s wedding.</strong></p><ul><li>A. it</li><li>B. when</li><li>C. which</li><li>D. what</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（when）</strong> —— 时刻是&quot;我参加婚礼的时候&quot; → when。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ it 不能引导表语从句；填 it 会让两个句子直接并列。</li><li>B ✅ 表语从句 I attended my best friend&#39;s wedding 完整，需要“在……的时候”这层时间含义 → when。</li><li>C ❌ which 要在从句里作主语或宾语，而本句从句完整。</li><li>D ❌ what 要在从句里作成分，也不能表示时间含义。</li></ul><p><strong>整句翻译</strong>：我最幸福的时刻是我参加最好的朋友婚礼的时候。</p><p><strong>词组</strong>：<code>attend a wedding</code> 参加婚礼；<code>best friend</code> 最好的朋友</p><p><strong>对比自测</strong>：做完后对照 quiz:25，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第二部分 · 四条大何）：连接副词“四条大何” when / where / why / how：不作主要成分，有含义。</p></details><p><strong>Please put the glass on the top shelf. It’s ____ the glass is beyond the reach of our children.</strong></p><ul><li>A. what</li><li>B. that</li><li>C. where</li><li>D. why</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（where）</strong> —— 表语从句：放在架子顶层，&quot;那里&quot;孩子够不着 → where。（beyond the reach of：超出……的能力范围；够不着）</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ what 要在从句里作成分，而 the glass is beyond the reach of our children 完整。</li><li>B ❌ 从句完整可以用 that 连接，但句意需要“在那里”的地点含义，that 无含义。</li><li>C ✅ 前一句交代“放在最上层”，从句完整、缺地点含义 → 用 where。</li><li>D ❌ why 表原因，本句说的是地点。</li></ul><p><strong>整句翻译</strong>：请把杯子放在最上层的架子上。放在那里，孩子就够不到这个杯子了。</p><p><strong>词组</strong>：<code>beyond the reach of</code> 超出……能够到的范围；够不着；<code>the top shelf</code> 最上层的架子</p><p><strong>对比自测</strong>：做完后对照 quiz:24，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第五部分 · 表语从句）：置于系动词后起表语作用的从句。引导词：除 if 外的一般引导词 + why + because + as though/if。</p></details><p><strong>We heard the news ____ our team had won the game.</strong></p><ul><li>A. what</li><li>B. that</li><li>C. which</li><li>D. when</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（that）</strong> —— news 是抽象名词，that 从句说明其内容 → 同位语从句，that 不作成分不可省略。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ what 要在从句里作成分，而 our team had won the game 完整。</li><li>B ✅ the news 是抽象名词，后面的从句说明“消息的内容”→ 同位语从句；从句完整、无含义 → that（不可省略）。</li><li>C ❌ 从句完整，which 没有位置；说明内容也不用 which。干扰点：见到名词后紧跟从句就当成定语从句。</li><li>D ❌ when 表时间，而从句 our team had won the game 完整，句子也不需要时间含义。</li></ul><p><strong>整句翻译</strong>：我们听说了我们队赢得比赛的消息。</p><p><strong>词组</strong>：<code>win the game</code> 赢得比赛</p><p><strong>对比自测</strong>：做完后对照 quiz:1，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第六部分 · 同位语从句）：作某一抽象名词的同位语，一般位于该名词之后，解释和说明该名词的具体内容</p></details><p><strong>This is the fact ____ he refused to accept the invitation.</strong></p><ul><li>A. which</li><li>B. why</li><li>C. that</li><li>D. when</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（that）</strong> —— fact 后同位语从句 → that。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 从句 he refused to accept the invitation 完整，which 没有位置。</li><li>B ❌ why 表原因；本句说的是“他拒绝邀请”这件事的内容，不是原因。</li><li>C ✅ the fact 是抽象名词 → 后面的从句说明事实内容；从句完整、无含义 → that（不可省略）。</li><li>D ❌ when 表时间，而从句完整，句子也不需要时间含义。</li></ul><p><strong>整句翻译</strong>：这就是他拒绝接受邀请这一事实。</p><p><strong>词组</strong>：<code>refuse to do sth.</code> 拒绝做某事；<code>accept the invitation</code> 接受邀请</p><p><strong>对比自测</strong>：做完后对照 quiz:28，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第六部分 · 同位语从句）：引导词：that（无实义，不可省略）；when、where、why、how、whether 等。</p></details><p><strong>The evidence ____ too much exposure to the sun is closely linked to skin cancer is convincing.</strong></p><ul><li>A. why</li><li>B. that</li><li>C. what</li><li>D. which</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（that）</strong> —— evidence 是抽象名词 → 同位语从句用 that。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ why 表原因，而从句说的是“证据的内容”。</li><li>B ✅ The evidence … is convincing 是主句主干，中间的从句说明 evidence 的内容且完整 → 同位语从句用 that。</li><li>C ❌ 从句 too much exposure to the sun is closely linked to skin cancer 完整，what 没有位置。</li><li>D ❌ 从句完整，which 没有位置。</li></ul><p><strong>整句翻译</strong>：过度暴露在阳光下与皮肤癌密切相关的证据很有说服力。</p><p><strong>词组</strong>：<code>be linked to</code> 与……有关联；<code>be convincing</code> 有说服力的</p><p><strong>对比自测</strong>：做完后对照 quiz:27，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第六部分 · 同位语从句）：常见名词：idea、fact、news、hope、belief、thought、doubt、promise、suggestion、order、possibility 等</p></details><p><strong>The fact ____ Helen was late for the weekly meeting again made the manager very angry.</strong></p><ul><li>A. why</li><li>B. that</li><li>C. what</li><li>D. which</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（that）</strong> —— fact 后同位语从句 → that。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ why 表原因；本句说的是“她迟到这件事”，不是原因。</li><li>B ✅ The fact … made the manager very angry 是主句主干，中间的从句说明 fact 的内容且完整 → 用 that。</li><li>C ❌ 从句 Helen was late for the weekly meeting again 完整，what 没有位置。</li><li>D ❌ 从句完整，which 没有位置。</li></ul><p><strong>整句翻译</strong>：海伦又一次在每周例会上迟到这一事实让经理非常生气。</p><p><strong>词组</strong>：<code>be late for</code> 迟到；<code>weekly meeting</code> 每周例会</p><p><strong>对比自测</strong>：做完后对照 quiz:30，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第六部分 · 同位语从句）：The fact that Ma is rich is true.（说明 the fact 的内容）</p></details><p><strong>There is an idea ____ too much stress can partly cause the disease.</strong></p><ul><li>A. what</li><li>B. which</li><li>C. as</li><li>D. that</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（that）</strong> —— idea 后同位语从句 → that。（partly：在一定程度上）</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 从句 too much stress can partly cause the disease 完整，what 没有位置。</li><li>B ❌ 从句完整，which 没有位置。</li><li>C ❌ as 不引导同位语从句。干扰点：把 as 当成通用连接词。</li><li>D ✅ an idea 是抽象名词，后面的从句说明其内容；从句完整、无含义 → that（不可省略）。</li></ul><p><strong>整句翻译</strong>：有一种看法认为，过多的压力在一定程度上会导致这种疾病。</p><p><strong>词组</strong>：<code>too much stress</code> 过多的压力（stress 不可数，用 too much 修饰）；<code>cause the disease</code> 引发这种疾病</p><p><strong>对比自测</strong>：做完后对照 quiz:29，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第六部分 · 同位语从句）：常见名词：idea（主意）、fact（事实）、news（新闻）、hope（希望）等。</p></details><p><strong>Our coach told us that the key to winning is to have the belief ____ we are better than anyone else on the sports field.</strong></p><ul><li>A. how</li><li>B. that</li><li>C. which</li><li>D. whether</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（that）</strong> —— belief 后同位语从句 → that。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ how 表方式；从句 we are better than anyone else on the sports field 完整，句意也不需要方式含义。</li><li>B ✅ the belief 是抽象名词 → 后面的从句说明信念的内容；从句完整、无含义 → that。</li><li>C ❌ 从句完整，which 没有位置。</li><li>D ❌ whether 表“是否”，而从句是肯定的断言“我们比任何人都强”。</li></ul><p><strong>整句翻译</strong>：我们的教练告诉我们，取胜的关键是要有这样一种信念：在赛场上我们比任何人都强。</p><p><strong>词组</strong>：<code>the key to doing sth.</code> 做某事的关键（to 是介词，后接动名词）；<code>have the belief that…</code> 抱着……的信念</p><p><strong>对比自测</strong>：做完后对照 quiz:26，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第六部分 · 同位语从句）：作某一抽象名词的同位语，一般位于该名词之后，解释和说明该名词的具体内容。</p></details><p><strong>It is generally considered unwise to give a child ____ he or she wants.</strong></p><ul><li>A. however</li><li>B. whatever</li><li>C. whichever</li><li>D. whenever</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（whatever）</strong> —— give a child whatever he or she wants 给孩子&quot;任何他想要的&quot;，泛指 → whatever。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ however 表“无论如何”，是副词，不能作 wants 的宾语。</li><li>B ✅ 从句 ____ he or she wants 里 wants 缺宾语 → 用 whatever（= anything that），表示“任何他想要的东西”，是泛指。</li><li>C ❌ whichever 表“其中任何一个”，需要明确的选择范围，本句没有范围。</li><li>D ❌ whenever 表“无论何时”，只能作时间状语，不能作宾语。</li></ul><p><strong>整句翻译</strong>：人们普遍认为，孩子要什么就给什么是不可取的。</p><p><strong>词组</strong>：<code>it is considered unwise to do sth.</code> 做某事被认为是不明智的；<code>whatever = anything that</code> 任何……的东西（表泛指）</p><p><strong>对比自测</strong>：做完后对照 quiz:43，比较两题的判断依据</p><p><strong>原文定位</strong>（课件易错清单）：whoever = anyone who（泛指）≠ who（特指）</p></details><p><strong>—Could you do me a favor? —It depends on ____ it is.</strong></p><ul><li>A. which</li><li>B. whichever</li><li>C. what</li><li>D. whatever</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（what）</strong> —— depends on 后介词宾语从句缺表语 → what it is（&quot;是什么忙&quot;）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ which 表“哪一个”，需要选择范围，本句没有。</li><li>B ❌ whichever 表“无论哪一个”，既需要范围，含义也太泛。</li><li>C ✅ on 是介词，后面是介词宾语从句；从句 it is 缺表语 → 用连接代词 what（“是什么忙”）。</li><li>D ❌ whatever 是泛指“无论什么”；这里指的是“这个忙”，是特指。</li></ul><p><strong>整句翻译</strong>：——你能帮我个忙吗？——那得看是什么忙。</p><p><strong>词组</strong>：<code>do sb. a favor</code> 帮某人一个忙；<code>depend on</code> 取决于、视……而定</p><p><strong>对比自测</strong>：做完后对照 quiz:21，比较两题的判断依据</p><p><strong>原文定位</strong>（课件易错清单）：what = 什么（物）；whoever = anyone who（泛指）≠ who（特指）</p></details><p><strong>Elephants have their own way to tell the shape of an object and ____ it is rough or smooth.</strong></p><ul><li>A. /</li><li>B. whether</li><li>C. how</li><li>D. what</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（whether）</strong> —— whether...or not 表&quot;是粗糙还是光滑&quot;（是否）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 不填则并列的两个从句之间缺少“是……还是……”的连接含义，表达不出“是否”。</li><li>B ✅ whether … or … 表“是……还是……、是否”，与后面的 or 呼应。</li><li>C ❌ how 表方式，而从句 it is rough or smooth 完整，句意要的是“是否”。</li><li>D ❌ what 要在从句里作成分，本句从句完整。</li></ul><p><strong>整句翻译</strong>：大象有自己的一套办法来判断一个物体的形状，以及它是粗糙还是光滑。</p><p><strong>词组</strong>：<code>tell the shape of an object</code> 分辨物体的形状；<code>rough or smooth</code> 粗糙还是光滑</p><p><strong>对比自测</strong>：做完后对照 quiz:41，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第四部分 · whether or not 结构）：Let me know whether you can come or not.</p></details><p><strong>I drove to Zhuhai for the air show last week. It is ____ I had a few days off.</strong></p><ul><li>A. why</li><li>B. when</li><li>C. what</li><li>D. where</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（why）</strong> —— &quot;那就是为什么我有几天假&quot;——解释原因 → why（It is why... = That is why）。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 表语从句解释“那就是……的原因”，用 why；对应结构 It is why… = That is why…。</li><li>B ❌ when 表时间；从句 I had a few days off 完整，句意解释的是原因。</li><li>C ❌ what 要在从句里作成分，本句从句完整。</li><li>D ❌ where 表地点；从句不缺地点含义。</li></ul><p><strong>整句翻译</strong>：上周我开车去珠海看航展。这就是我休了几天假的原因。</p><p><strong>词组</strong>：<code>the air show</code> 航空展；<code>have a few days off</code> 休几天假</p><p><strong>对比自测</strong>：做完后对照 quiz:24，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第五部分 · 三组固定结构）：This/That/It is/was why…：那就是……的原因：He was caught in a traffic jam. That was why he was late.</p></details><p><strong>—Do you know ____ the meeting will start? —At 3:00 this afternoon.</strong></p><ul><li>A. when</li><li>B. where</li><li>C. why</li><li>D. how</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（when）</strong> —— 答语 At 3:00 是时间 → when。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 答语 At 3:00 this afternoon 是时间；宾语从句 the meeting will start 完整、缺时间含义 → when。</li><li>B ❌ where 表地点，答语给的是时间。</li><li>C ❌ why 表原因，答语给的是时间。</li><li>D ❌ how 表方式，答语给的是时间。</li></ul><p><strong>整句翻译</strong>：——你知道会议什么时候开始吗？——今天下午三点。</p><p><strong>词组</strong>：<code>at 3:00 this afternoon</code> 今天下午三点</p><p><strong>对比自测</strong>：做完后对照 quiz:18，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第二部分 · 四条大何）：连接副词 when / where / why / how：不作主要成分，有含义</p></details><p><strong>____ is known to us all is that the 2022 Winter Olympics will be held in Beijing.</strong></p><ul><li>A. As</li><li>B. What</li><li>C. It</li><li>D. That</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（What）</strong> —— 主语从句缺主语 → What；As 不能引导带谓语 is 的主语从句放句首。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ As 不能引导带谓语 is 的主语从句放在句首。干扰点：把 As is known to us all（正如大家所知）这个说法直接搬来。</li><li>B ✅ 第二个 is 前面缺主语 → 用连接代词 What，构成 What is known to us all 作主语从句。</li><li>C ❌ It 不能连接后面的 is；本句缺的是主语从句的引导词，而且是“两空”结构里的第一空。</li><li>D ❌ is known to us all 里 is 前缺主语，从句不完整 → 不能用 that。</li></ul><p><strong>整句翻译</strong>：我们大家都知道的是，2022 年冬奥会将在北京举行。</p><p><strong>词组</strong>：<code>be known to us all</code> 我们大家都知道；<code>be held</code> 被举行</p><p><strong>对比自测</strong>：做完后对照 quiz:39，比较两题的判断依据</p><p><strong>原文定位</strong>（课件易错清单）：What…is that… 主语从句缺主语用 What；As 不能单独引导主语从句作主语（需逗号非限或 It is known that）</p></details><p><strong>____ is reported that the 2022 Winter Olympics will be held in Beijing.</strong></p><ul><li>A. As</li><li>B. What</li><li>C. It</li><li>D. That</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（It）</strong> —— It is reported that... 固定句型（It 作形式主语）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ As is reported 通常作非限制性定语从句（“正如报道的那样”），不能直接接 that 从句作主语。</li><li>B ❌ what 要在从句里作成分；本句已经有 that 从句作真正的主语。</li><li>C ✅ It is reported that… 是固定句型，it 作形式主语，真正的主语是 that 从句。</li><li>D ❌ 填 That 会构成主语从句 That the 2022 Winter Olympics… 再接 is reported，结构重复。</li></ul><p><strong>整句翻译</strong>：据报道，2022 年冬奥会将在北京举行。</p><p><strong>词组</strong>：<code>It is reported that…</code> 据报道……（it 作形式主语）</p><p><strong>对比自测</strong>：做完后对照 quiz:7，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第三部分 · 形式主语）：It is + 分词 + that：It is reported that she will go abroad soon. = She is reported to go abroad soon.</p></details><p><strong>____ is known to us all that the 2022 Winter Olympics will be held in Beijing.</strong></p><ul><li>A. as</li><li>B. what</li><li>C. it</li><li>D. that</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（it）</strong> —— It is known to us all that... 固定句型。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ as 引导非限制性定语从句时要加逗号（As is known to all, …），不能直接填在句首作形式主语。</li><li>B ❌ what 要在从句里作成分；本句有 that 从句作真正的主语。</li><li>C ✅ It is known to us all that… 是固定句型，it 作形式主语。</li><li>D ❌ 填 that 会与后面真正的 that 从句重复，结构不成立。</li></ul><p><strong>整句翻译</strong>：我们大家都知道，2022 年冬奥会将在北京举行。</p><p><strong>词组</strong>：<code>It is known to us all that…</code> 我们都知道……</p><p><strong>对比自测</strong>：做完后对照 quiz:37，比较两题的判断依据</p><p><strong>原文定位</strong>（课件易错清单）：As 不能单独引导主语从句作主语（需逗号非限或 It is known that）</p></details><p><strong>Along with the letter was his promise ____ he would visit me this coming Christmas.</strong></p><ul><li>A. which</li><li>B. that</li><li>C. whether</li><li>D. what</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（that）</strong> —— promise 后同位语从句 → that。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 从句 he would visit me this coming Christmas 完整，which 没有位置。</li><li>B ✅ his promise 是抽象名词，后面的从句说明承诺的内容；从句完整、无含义 → that（不可省略）。</li><li>C ❌ whether 表“是否”，而从句是肯定的承诺内容。</li><li>D ❌ what 要在从句里作成分，本句从句完整。</li></ul><p><strong>整句翻译</strong>：随信而来的是他的承诺：这个即将到来的圣诞节他会来看我。</p><p><strong>词组</strong>：<code>along with</code> 与……一起；<code>this coming Christmas</code> 即将到来的这个圣诞节</p><p><strong>对比自测</strong>：做完后对照 quiz:31，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第六部分 · 同位语从句）：常见名词：…doubt（怀疑）、promise（承诺）、suggestion（建议）、order（命令）、possibility（可能）等。</p></details><p><strong>Juliet has gone to Milan and I wonder ____ she can make it to（赶到）our wedding or not.</strong></p><ul><li>A. when</li><li>B. that</li><li>C. if</li><li>D. whether</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（whether）</strong> —— 与 or not 连用必须用 whether，不用 if。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ when 表时间；从句 she can make it to our wedding 完整，而 or not 提示含义是“是否”。</li><li>B ❌ that 无含义，与 or not 的“是否”语义不符。</li><li>C ❌ if 不能与 or not 直接连用。干扰点：以为宾语从句里的“是否”都能用 if。</li><li>D ✅ wonder 后面是宾语从句，从句与 or not 连用表“是否”→ 只能用 whether。</li></ul><p><strong>整句翻译</strong>：朱丽叶去了米兰，我想知道她能不能赶上我们的婚礼。</p><p><strong>词组</strong>：<code>make it to</code> 赶到、及时到达</p><p><strong>对比自测</strong>：做完后对照 quiz:34，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第四部分 · 用 whether 不用 if 的 7 种情况）：2. whether or not 结构中：Let me know whether you can come or not.</p></details><p><strong>We consider ____ he should clean the room by himself every day.</strong></p><ul><li>A. that it necessary</li><li>B. necessary it that</li><li>C. it that necessary</li><li>D. it necessary that</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（it necessary that）</strong> —— consider + it + necessary + that：it 作形式宾语，语序为 it necessary that。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 语序错误：形式宾语 it 要紧紧跟在动词 consider 后面，不能把 that 放在它前面。</li><li>B ❌ 语序错误：形容词 necessary 应放在形式宾语 it 之后。</li><li>C ❌ 语序错误：that 从句要放在形容词之后，不能插在 it 与形容词中间。</li><li>D ✅ consider + it + necessary + that 从句：it 作形式宾语，真正宾语是 that he should clean the room by himself every day。</li></ul><p><strong>整句翻译</strong>：我们认为他每天应当自己打扫房间是必要的。</p><p><strong>词组</strong>：<code>clean the room</code> 打扫房间；<code>by himself</code> 他自己（亲自）</p><p><strong>对比自测</strong>：做完后对照 quiz:13，比较两题的判断依据</p><p><strong>原文定位</strong>（课件第四部分 · that 不能省略）：find/believe/think/consider/make + it + adj. + that 宾从句型中不省略</p></details><p><strong>In order to search for the escaped prisoner, the police decide to question ____ comes along on this road.</strong></p><ul><li>A. who</li><li>B. whom</li><li>C. whoever</li><li>D. whomever</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（whoever）</strong> —— 课件原解析：从句中 comes 为谓语，其前缺主语，排除 B/D；who 引导宾语从句通常表特指，whoever = anyone who 表泛指&quot;无论谁&quot;，符合&quot;盘问所有出现在这条路上的人&quot;。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ who 引导宾语从句通常表特指（“谁”），而这里要表达“所有出现在这条路上的人”，是泛指。干扰点：只注意从句缺主语。</li><li>B ❌ 从句 comes 前缺主语，whom 只能作宾语，不能作主语。</li><li>C ✅ whoever = anyone who，表泛指，并且在从句里作主语（comes 前缺主语）。</li><li>D ❌ whomever 只能作宾语，而这里从句缺的是主语。</li></ul><p><strong>整句翻译</strong>：为了搜寻逃犯，警方决定盘问所有出现在这条路上的人。</p><p><strong>词组</strong>：<code>search for</code> 搜寻；<code>escaped prisoner</code> 逃犯；<code>come along</code> 出现、走过来</p><p><strong>对比自测</strong>：做完后对照 quiz:32，比较两题的判断依据</p><p><strong>原文定位</strong>（课件易错清单）：whoever = anyone who（泛指）≠ who（特指）</p></details><h2 id="口诀卡" tabindex="-1"><a class="header-anchor" href="#口诀卡"><span>口诀卡</span></a></h2><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>本课全部口诀 四步法：<strong>划从句 → 看类型 → 看成分 → 看含义</strong></p><p>引导词：<strong>不缺成分 → that（无义）/ whether（是否）/ 四条大何（when/where/why/how 有义）；缺成分 → 5W 连接代词</strong></p><p>表语从句：<strong>reason → that；That is because 原因，That is why 结果</strong></p><p>whether 必用：<strong>介前、句首、to do、or not、讨论决定怀疑（discuss/decide/doubt）、主表同位</strong></p><p>同位语从句抽象名词：<strong>idea, fact, news, hope, belief, thought, doubt, promise, suggestion, order, possibility</strong></p></div><p>延伸阅读：名词性从句 · 完整笔记 · 原始课件 PDF</p><p>有不懂的随时问你的 AI 老师——回到 ZCode 对话里直接提问即可。</p><hr>`,228),a(`p`,null,[o(m,{href:`/courses/zsb-english/l/12/`},{default:i(()=>[...l[5]||=[e(`← 第 12 课`,-1)]]),_:1}),l[8]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/`},{default:i(()=>[...l[6]||=[e(`课程目录`,-1)]]),_:1}),l[9]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/l/14/`},{default:i(()=>[...l[7]||=[e(`第 14 课 →`,-1)]]),_:1})])])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};